FROM repair_order r WHERE r.del_flag = 0
AND (r.tenant_id = #{userId} OR r.landlord_id = #{userId})
AND r.status = #{status}

mapper.select:
SELECT 

ORDER BY r.create_time DESC
LIMIT #{offset}, #{limit}

mapper.update:
UPDATE repair_order
SET status = #{toStatus}, version = version + 1, update_time = NOW()
, accepted_by = #{acceptedBy}
, accepted_at = #{acceptedAt}
, arrived_at = #{arrivedAt}
, completed_at = #{completedAt}
, confirmed_at = #{confirmedAt}
, cancel_reason = #{cancelReason}
, tenant_score = #{tenantScore}
, tenant_comment = #{tenantComment}
WHERE id = #{id} AND version = #{version} AND status = #{fromStatus} AND del_flag = 0

